-- 1) 기본 개방을 닫는다 (ACCOUNTADMIN)
REVOKE USE AI FUNCTIONS ON ACCOUNT FROM ROLE PUBLIC;

-- 2) 고객지원 역할에만 함수 단위 권한을 준다
GRANT USE AI FUNCTION AI_COMPLETE ON ACCOUNT
  TO ROLE support_role;

-- 3) 필요한 데이터베이스 역할도 함께 준다
GRANT DATABASE ROLE SNOWFLAKE.CORTEX_USER
  TO ROLE support_role;

-- 4) 역할을 사용자에게 부여한다
GRANT ROLE support_role TO USER example_user;
